const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches

const FONT = '微软雅黑';
const COLOR_PRIMARY = '1F4E79';
const COLOR_ACCENT = '2E75B6';
const COLOR_LIGHT_BG = 'D6E4F0';
const COLOR_WHITE = 'FFFFFF';
const COLOR_DARK_TEXT = '333333';
const COLOR_SUBTITLE = '555555';

// Helper: add a colored top bar to a slide
function addTopBar(slide) {
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 0.15, fill: { color: COLOR_PRIMARY }
  });
}

// Helper: add page number
function addPageNum(slide, num, total) {
  slide.addText(`${num} / ${total}`, {
    x: 11.5, y: 7.0, w: 1.5, h: 0.4,
    fontSize: 10, fontFace: FONT, color: '999999', align: 'right'
  });
}

// ==================== Slide 1: Title ====================
const s1 = pres.addSlide();
s1.background = { color: COLOR_PRIMARY };
s1.addText('团队协作', {
  x: 1.0, y: 1.8, w: 11.33, h: 1.5,
  fontSize: 48, fontFace: FONT, bold: true, color: COLOR_WHITE, align: 'center'
});
s1.addText('打造高效协同的团队文化', {
  x: 1.0, y: 3.3, w: 11.33, h: 0.8,
  fontSize: 24, fontFace: FONT, color: 'B0C4DE', align: 'center'
});
s1.addShape(pres.ShapeType.rect, {
  x: 5.0, y: 4.3, w: 3.33, h: 0.04, fill: { color: COLOR_WHITE }
});
s1.addText('2024 年度团队发展计划', {
  x: 1.0, y: 4.8, w: 11.33, h: 0.6,
  fontSize: 16, fontFace: FONT, color: 'D0D0D0', align: 'center'
});

// ==================== Slide 2: Why Team Collaboration Matters ====================
const s2 = pres.addSlide();
addTopBar(s2);
s2.addText('为什么团队协作至关重要？', {
  x: 0.6, y: 0.4, w: 12.0, h: 0.8,
  fontSize: 30, fontFace: FONT, bold: true, color: COLOR_PRIMARY
});

const reasons = [
  { title: '提升效率', desc: '合理分工与协同减少重复劳动，\n缩短项目交付周期 30%+' },
  { title: '激发创新', desc: '多元视角碰撞产生创意方案，\n跨职能协作催生突破性成果' },
  { title: '增强韧性', desc: '信息共享与互信降低单点风险，\n团队面对变化更具适应力' },
  { title: '提升满意度', desc: '归属感与心理安全感提高敬业度，\n降低人才流失率' }
];

reasons.forEach((r, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const bx = 0.6 + col * 6.2;
  const by = 1.6 + row * 2.7;

  s2.addShape(pres.ShapeType.roundRect, {
    x: bx, y: by, w: 5.8, h: 2.3, rectRadius: 0.15,
    fill: { color: COLOR_LIGHT_BG }, line: { color: COLOR_ACCENT, width: 1 }
  });
  s2.addText(r.title, {
    x: bx + 0.3, y: by + 0.2, w: 5.2, h: 0.6,
    fontSize: 20, fontFace: FONT, bold: true, color: COLOR_PRIMARY
  });
  s2.addText(r.desc, {
    x: bx + 0.3, y: by + 0.85, w: 5.2, h: 1.2,
    fontSize: 14, fontFace: FONT, color: COLOR_DARK_TEXT, lineSpacingMultiple: 1.3
  });
});
addPageNum(s2, 2, 5);

// ==================== Slide 3: Core Principles ====================
const s3 = pres.addSlide();
addTopBar(s3);
s3.addText('高效协作的四大核心原则', {
  x: 0.6, y: 0.4, w: 12.0, h: 0.8,
  fontSize: 30, fontFace: FONT, bold: true, color: COLOR_PRIMARY
});

const principles = [
  { icon: '🎯', title: '目标对齐', points: ['共同愿景与OKR牵引方向', '定期同步进度与优先级', '个人目标与团队目标挂钩'] },
  { icon: '💬', title: '透明沟通', points: ['信息主动公开、减少壁垒', '反馈及时且建设性', '多渠道沟通（异步+同步）'] },
  { icon: '🤝', title: '信任授权', points: ['明确角色与责任边界', '给予自主决策空间', '容错文化鼓励尝试'] },
  { icon: '🔄', title: '持续改进', points: ['复盘机制常态化', '流程工具迭代优化', '学习分享促进成长'] }
];

principles.forEach((p, i) => {
  const bx = 0.4 + i * 3.15;
  const by = 1.6;

  // Card background
  s3.addShape(pres.ShapeType.roundRect, {
    x: bx, y: by, w: 2.95, h: 5.2, rectRadius: 0.15,
    fill: { color: COLOR_WHITE }, line: { color: COLOR_ACCENT, width: 1 },
    shadow: { type: 'outer', blur: 4, offset: 2, color: 'CCCCCC', opacity: 0.3 }
  });

  // Icon circle
  s3.addShape(pres.ShapeType.ellipse, {
    x: bx + 0.85, y: by + 0.3, w: 1.25, h: 1.25,
    fill: { color: COLOR_LIGHT_BG }
  });
  s3.addText(p.icon, {
    x: bx + 0.85, y: by + 0.3, w: 1.25, h: 1.25,
    fontSize: 36, align: 'center', valign: 'middle'
  });

  // Title
  s3.addText(p.title, {
    x: bx + 0.15, y: by + 1.7, w: 2.65, h: 0.6,
    fontSize: 18, fontFace: FONT, bold: true, color: COLOR_PRIMARY, align: 'center'
  });

